// TH15 v1.00b Stage 1 中BossB 非符 MBossB1
// 源: st01mbs2.ecl.txt:57-76 (MBossB1), 依赖 78-171 (MBossB1_at)
// 入口状态: st01mbs2.ecl.txt:8-55 (位置/限位/框; timerReset 后 40 帧进入本段)
// 源 type13/color8 -> TH15_BULLET; type18/color4 -> TH15_BIG_BALL
const TH15_BULLET: int = 560;
const TH15_BIG_BALL: int = 640;

const OPENING_BUFFER: int = 120;
// 120 缓冲 + 剩余 1460 + 4 启动余量
const TIME_LIMIT: int = 1584;

// 源 moveLimit(0, 128, 280, 256): x ∈ [-140,140], y ∈ [0,256]
// moveRand 方向内区为中心 ± 宽高/4: x ±70, y [64,192]
sub card_arm_next_step() {
    var k: int = self_int(0) + 1;
    set_self_int(0, k);
    var speed: fx = 0fx;
    if k < 60 { speed = (60 - k) as fx / 60; }
    var nx: fx = $self_x + self_fx(0) * speed;
    var ny: fx = $self_y + self_fx(1) * speed;
    if nx < -140fx { nx = -140fx; }
    if nx > 140fx { nx = 140fx; }
    if ny < 0fx { ny = 0fx; }
    if ny > 256fx { ny = 256fx; }
    move_vel_xy(0, nx - $self_x, ny - $self_y, EASE_LINEAR);
}

sub card_begin_angle(a: angle) {
    set_self_fx(0, cos(a));
    set_self_fx(1, sin(a));
    set_self_int(0, 0);
    card_arm_next_step();
}

// 源 412 moveRand(60,4,1.0f): 每次调用抽一次固定方向, 速度 1-k/60 线性降到 0。
sub card_move_rand() {
    var r: int = rand(65536) - 32768;
    var a: int = r / 3;
    if $self_x < -70fx {
        a = r / 3;
    } else if $self_x > 70fx {
        a = r / 3 + 32768;
        if a > 32768 { a = a - 65536; }
    } else {
        a = r / 4;
        var choose: int = rand(65536) % 3;
        if $player_x > $self_x {
            if choose == 0 { a = a + 32768; }
        } else {
            if choose != 0 { a = a + 32768; }
        }
    }
    if $self_y < 64fx {
        if a < 0 { a = -a; }
    } else if $self_y > 192fx {
        if a < 0 { a = -a; }
        a = -a;
    }
    if a > -16906 && a < -15862 {
        if a < -16384 { a = -16906; } else { a = -15862; }
    } else if a > 15862 && a < 16906 {
        if a < 16384 { a = 15862; } else { a = 16906; }
    }
    card_begin_angle(a as angle);
}

sub card_wait(frames: int) {
    for i in 0..frames {
        wait(1);
        card_arm_next_step();
    }
}

// 源 etAim mode1 固定方向扇形; 路数 n, 相邻夹角 spread, 中心 base。
// 源 ANIM a=1 在效果进入时执行 position -= 4*velocity, 按初速保留出生退位移。
sub emit_fan(shape: int, color: int, x: fx, y: fx, base: angle, spread: angle, n: int, speed: fx) {
    var step: int = spread as int;
    var half: int = ((n - 1) * step) / 2;
    var back: fx = 4fx * speed;
    for i in 0..n {
        var a: angle = base + ((i * step - half) as angle);
        _ = fire(shape, color, x - back * cos(a), y - back * sin(a), speed, a, none, none);
    }
}

// 源 MBossB1_at(A,B,C); 本文件只使用 A(首段累计起点, 恒0)与 C(每步角增量)。
// B 在源函数体内未被读取(首段夹角写死 2 度), 故不传入。
// x/y/aim 在 spawn 当帧从 Boss 取快照, 避免 spawn 次帧启动造成的位置漂移。
async sub mb1_at(x: fx, y: fx, aim: angle, cstep: angle) {
    var rank: int = global(GVAR_RANK);
    var speed: fx = 1.5fx;
    var g: int = 4;
    var h: int = 1;
    var w1: int = 6;
    var w2: int = 6;
    var spread2: angle = 30deg;
    if rank == 1 {
        speed = 2fx; g = 8; h = 2; w1 = 5; w2 = 6; spread2 = 20deg;
    } else if rank == 2 {
        speed = 3.1fx; g = 8; h = 8; w1 = 3; w2 = 5; spread2 = 20deg;
    } else if rank >= 3 {
        speed = 4.1fx; g = 12; h = 12; w1 = 2; w2 = 2; spread2 = 12deg;
    }
    var c_bam: int = cstep as int;
    var g1: int = g + 1;
    // 首段: 弹型13, 2 度扇形, 1..G 路, 角度 aim + k*C
    for k in 1..g1 {
        emit_fan(TH15_BULLET, 8, x, y, aim + ((k * c_bam) as angle), 2deg, k, speed);
        wait(w1);
    }
    // 次段: 弹型18, 难度夹角, G+1..G+H 路, 角度 90 度 + (G+k)*C
    var h1: int = h + 1;
    for j in 1..h1 {
        var m: int = g + j;
        emit_fan(TH15_BIG_BALL, 4, x, y, 90deg + ((m * c_bam) as angle), spread2, m, speed);
        wait(w2);
    }
}

async sub boss_main() {
    set_invuln(65535);
    // 源 setHurtbox(48,48)/setHitbox(40,40): 普通圆形取第一值*0.5
    set_hurtbox(24fx);
    set_hitbox(20fx);
    // 入口已完成 40/100 帧 movePosTime(100,4,0,128); 二次减速余段可按同曲线续 60 帧。
    move_to(60, 0fx, 128fx, EASE_QUAD_OUT);
    // 源 MBossB1 入口 EffChargePoint3(纯表现) + wait(160)
    wait(160);
    loop {
        spawn mb1_at($self_x, $self_y, aim_player(), -10deg);
        card_wait(60);
        card_move_rand();
        card_wait(80);
        spawn mb1_at($self_x, $self_y, aim_player(), 10deg);
        card_wait(60);
        spawn mb1_at($self_x, $self_y, aim_player(), -10deg);
        card_wait(60);
        card_move_rand();
        card_wait(80);
    }
}

async sub pattern() {
    wait(OPENING_BUFFER);
    // 源入口位置: movePosTime 已过 40 帧, u=0.4 -> (69.12, 58.88)
    _ = spawn_enemy(69.12fx, 58.88fx, 1000, 0, 0, 0, boss_main);
}

async sub control() {
    set_invuln(65535);
    set_enemy_flag(ENEMY_NO_BODY, 1);
    phase_begin(0, pattern, TIME_LIMIT, 0);
    wait_spell();
    loop { wait(1); }
}

sub main() {
    _ = spawn_enemy(0fx, 0fx, 1000, 0, 0, 0, control);
    loop { wait(600); }
}
